package com.yeyamo_mobile.api.commerce_service.persistence;
import jakarta.persistence.*;import java.math.*;import java.time.*;import java.util.*;
@Entity @Table(name="artwork_orders")public class ArtworkOrder{
 public enum Status{PENDING,AWAITING_PAYMENT,PAID,ACCEPTED,IN_PRODUCTION,READY,SHIPPED,DELIVERED,CANCELLED,REFUNDED,DISPUTED}public enum DeliveryType{PICKUP,LOCAL_DELIVERY,DELIVERY_ON_REQUEST,INTERNATIONAL_SHIPPING}
 @Id public UUID id;public String reference;@Column(name="idempotency_key",unique=true)public String idempotencyKey;@Column(name="buyer_user_id")public String buyerUserId;@Column(name="artisan_partner_id")public String artisanPartnerId;@Column(name="offer_id")public UUID offerId;@Column(name="commerce_order_id")public UUID commerceOrderId;@Enumerated(EnumType.STRING)public Status status;@Enumerated(EnumType.STRING)@Column(name="delivery_type")public DeliveryType deliveryType;public int quantity;@Column(name="gross_amount")public BigDecimal grossAmount;@Column(name="commission_amount")public BigDecimal commissionAmount;@Column(name="artisan_amount")public BigDecimal artisanAmount;@Column(name="currency_code")public String currencyCode;@Column(name="cancellation_reason")public String cancellationReason;@Column(name="created_at")public Instant createdAt;@Column(name="updated_at")public Instant updatedAt;@Version public long version;@PrePersist void c(){createdAt=updatedAt=Instant.now();}@PreUpdate void u(){updatedAt=Instant.now();}
}
